package com.ecommerce.platform.dto;

import lombok.*;

import java.math.BigDecimal;

/**
 * Projection DTO for vendor analytics.
 * <p>
 * Used by the {@code OrderRepository}'s JPQL aggregation query to return
 * revenue and order count per vendor in a single database round-trip.
 */
@Getter @Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class VendorAnalyticsDto {

    /** The vendor's user ID. */
    private Long vendorId;

    /** Total revenue generated by this vendor's products across all orders. */
    private BigDecimal totalRevenue;

    /** Number of distinct orders containing this vendor's products. */
    private Long orderCount;
}
